$ErrorActionPreference='SilentlyContinue'
. (Join-Path $PSScriptRoot 'common.ps1');Initialize-YomiData;$config=Get-YomiConfig
$out=New-Object System.Collections.Generic.List[string];$out.Add('===== YOMI 4.0 DIAGNOSTICS =====');$out.Add('');$out.Add("Program: $InstallRoot");$out.Add("Data: $DataRoot");$out.Add("Mode: $($config.app_mode)");$out.Add("Player video: $($config.player_video_quality)");$out.Add("Performance: $($config.performance_mode) / $($config.cache_workers) worker(s)");$out.Add("Canvas: $($config.canvas_width)x$($config.canvas_height)  Corner: $($config.corner)");$out.Add("Modules: Art=$($config.artwork_enabled) Video=$($config.video_enabled) Viz=$($config.visualizer_enabled)");$out.Add('');$out.Add('===== COMPONENTS =====');foreach($n in @('mpv','ytdlp','deno','ffmpeg')){$i=Get-YomiComponentInfo $n;$out.Add("$n : Installed=$($i.Installed)  Size=$($i.SizeMB)MB  Version=$($i.Version)")}
$out.Add('');$out.Add('===== APP PROCESSES =====');Get-CimInstance Win32_Process|Where-Object{$_.CommandLine -like '*YOMI*' -or $_.ExecutablePath -like "$InstallRoot*"}|Select-Object -First 20|ForEach-Object{$out.Add("$($_.Name) PID $($_.ProcessId)")}
$out.Add('');$out.Add('===== CACHE COUNTS =====');foreach($d in @('audio','artwork','video','visualizer','meta','gain','status')){$count=@(Get-ChildItem (Join-Path $DataRoot "cache\$d") -File -ErrorAction SilentlyContinue).Count;$out.Add(("{0,-12} {1}" -f $d,$count))}
$mpvLog=Join-Path $DataRoot 'logs\mpv.log';$out.Add('');$out.Add('===== MPV LOG - LAST 35 USEFUL LINES =====');if(Test-Path $mpvLog){Get-Content $mpvLog -Tail 250|Where-Object{$_ -match '(?i)YOMI|error|fail|403|track|video|artwork|visualizer'}|Select-Object -Last 35|ForEach-Object{$clean=$_ -replace 'https?://\S+','<URL REMOVED>';if($clean.Length -gt 260){$clean=$clean.Substring(0,260)+'...'};$out.Add($clean)}}else{$out.Add('(no mpv log yet)')}
$text=$out -join "`r`n";try{Set-Clipboard -Value $text}catch{};$text;Write-Host '';Write-Host 'Diagnostics copied to clipboard.' -ForegroundColor Green
